export const SPEAKING_LESSON_IDS = SPEAKING_LESSONS.map((lesson) => lesson.id);
export type SpeakingLessonId = (typeof SPEAKING_LESSONS)[number]["id"];

export type SpeakingCourseLesson = {
  id: string;
  stage: string;
  title: string;
  minutes: number;
  goal: string;
  prompt: string;
  model: string;
  frame: string;
  drill: string;
  grammar?: string;
};

type SpokenBookLessonContent = Omit<SpeakingCourseLesson, "id" | "stage" | "minutes">;

// Original practice prompts and examples arranged around the 60-class outline in
// Munzereen Shahid's Ghore Boshe Spoken English book. The book's full lesson text
// is not reproduced here.
const SPOKEN_BOOK_CONTENT: SpokenBookLessonContent[] = [
  { title: "Introduce yourself", goal: "Share the basic facts about yourself in a calm, connected introduction.", prompt: "Introduce yourself to a new classmate. Include your name, where you live, what you do, and one interest.", model: "Hello, my name is Amina. I live in Dhaka, and I am studying business. In my free time, I enjoy reading and learning new skills. I am practising English so I can speak confidently with people from different backgrounds.", frame: "Hello, I'm ___. I live in ___. I study/work as ___. I enjoy ___. I'm learning English because ___.", drill: "Say the introduction once while reading, then again using only four keywords: name, place, work or study, interest.", grammar: "Use I am + noun/adjective, I live + place, and I enjoy + verb-ing." },
  { title: "Meet someone new", goal: "Start a friendly conversation and ask one natural follow-up question.", prompt: "Imagine you are waiting before a class starts. Greet a person, introduce yourself, and ask what they are learning.", model: "Hi, I'm Rafi. Is this your first class here? I am studying English in the evening because I want to communicate more easily at work. What brought you to the class?", frame: "Hi, I'm ___. Is this your first time here? I'm here because ___. What about you?", drill: "Practise the greeting with a warm tone. Pause after your question so the other person has room to answer.", grammar: "Questions often begin with Do, Are, Is, or What. Keep the helper verb before the subject." },
  { title: "Everyday sentences", goal: "Make useful short sentences for common moments in your day.", prompt: "Describe three things you often say or do in the morning, afternoon, and evening.", model: "I usually make tea before I start work. At lunchtime, I call my family if I have time. In the evening, I review my plans and practise English for a few minutes.", frame: "In the morning, I ___. At lunchtime, I ___. In the evening, I ___.", drill: "Choose one action for each part of the day. Connect the ideas with first, then, and later.", grammar: "For habits, use the present simple: I work, she works, they study." },
  { title: "Ask clear questions", goal: "Use simple question patterns to keep a conversation moving.", prompt: "Ask a new friend about their hometown, work or study, and favourite free-time activity.", model: "Where did you grow up? What do you do during the week? Which activity helps you relax after a busy day? I like asking open questions because they invite more than a yes-or-no answer.", frame: "Where do you ___? What do you ___? Which ___ do you like?", drill: "Ask each question aloud, then answer it yourself in one complete sentence.", grammar: "Use question word + do/does/did + subject + base verb: Where does she work?" },
  { title: "Describe a person in six steps", goal: "Describe a person with a clear order instead of listing disconnected adjectives.", prompt: "Describe someone you admire: who they are, how you know them, their appearance, personality, a habit, and why you admire them.", model: "My older cousin is someone I admire. She is a teacher with a cheerful smile. She listens carefully, works hard, and always encourages younger students. I respect her because she is patient and dependable.", frame: "I want to describe ___. I know them from ___. They look ___. They are ___. I admire them because ___.", drill: "Use one detail for each step. Avoid repeating the same adjective; add a small example of the person's character.", grammar: "Use be for qualities (She is patient) and present simple for habits (She helps people)." },
  { title: "Talk about the weather", goal: "Describe today's weather and explain how it affects your plans.", prompt: "What is the weather like today? Say how it makes you feel and what you plan to do.", model: "It is warm and cloudy today, so I may go for a short walk before it rains. I enjoy cool weather because it makes the city feel calmer. If the rain gets heavy, I will stay home and read.", frame: "Today it is ___. I feel ___ because ___. If ___, I will ___.", drill: "Describe the sky, temperature, and one effect on your day. Speak naturally rather than memorising a weather report.", grammar: "Use It is + adjective for weather. Use if + present, will + verb for a possible plan." },
  { title: "Say thank you and respond politely", goal: "Thank someone specifically and reply naturally when they thank you.", prompt: "Thank a friend for helping you prepare for an important meeting. Then practise a friendly reply.", model: "Thank you for helping me organise my notes. Your suggestions made the main points much clearer. I really appreciate the time you gave me. You are welcome; I was happy to help.", frame: "Thank you for ___. It helped me ___. I really appreciate ___. / You're welcome; ___.", drill: "Give a specific reason for your thanks. Practise two replies: a casual one and a more formal one.", grammar: "After thank you for, use a noun or verb-ing: Thank you for explaining." },
  { title: "Give a sincere compliment", goal: "Give a specific, respectful compliment and accept one comfortably.", prompt: "Compliment a colleague on a presentation, then practise how you would respond to a compliment.", model: "Your presentation was easy to follow, and the examples helped me understand the topic. Thank you, that is kind of you to say. I spent extra time organising the slides.", frame: "I liked your ___ because ___. / Thank you, that's kind of you. I ___.", drill: "Mention a real action or quality. Keep the compliment sincere and focused on effort, skill, or a choice.", grammar: "Use I liked + noun/verb-ing for past feedback; use because to add a reason." },
  { title: "Speak with your mother", goal: "Share a small update and ask a family member about their day.", prompt: "Tell your mother about one good thing and one difficult thing from today.", model: "Today went well because I finished an assignment before the deadline. The difficult part was travelling through heavy traffic. How was your day? Did you get time to rest this afternoon?", frame: "Today, I ___. I felt ___ when ___. The hardest part was ___. How was your day?", drill: "Use a warm, conversational voice. Add a follow-up question after your update.", grammar: "Use past simple for finished events: I finished, I travelled, I felt." },
  { title: "Bargain politely", goal: "Ask about a price, make a respectful offer, and agree or decline clearly.", prompt: "At a market, ask the seller for the price of a bag and see whether they can offer a lower price.", model: "How much is this bag? Would you be able to offer it for a little less? I have seen a similar one nearby. Thank you for considering it; I will take it at that price.", frame: "How much is ___? Could you offer it for ___? Would ___ work for you?", drill: "Keep your tone friendly. Practise accepting the price and politely deciding to look elsewhere.", grammar: "Use Could you/Would you for polite requests. Follow could with the base verb." },
  { title: "Welcome a guest", goal: "Greet a visitor, offer help, and make them feel comfortable.", prompt: "A guest has arrived at your home. Welcome them, offer a seat and a drink, and ask how their journey was.", model: "Welcome, please come in. You can leave your shoes by the door and make yourself comfortable. Would you like some tea or water? How was the journey? I hope the traffic was not too bad.", frame: "Welcome to ___. Please ___. Would you like ___? How was ___?", drill: "Practise with a relaxed pace. Offer one choice at a time so the guest can answer easily.", grammar: "Use would like for polite offers. Use How was + noun to ask about a finished experience." },
  { title: "Keep a daily conversation going", goal: "Connect short updates with a follow-up and a natural response.", prompt: "Talk with a neighbour about how your week is going and what you will do this weekend.", model: "My week has been busy, but I managed to finish a few important tasks. This weekend, I am planning to visit my aunt. What about you? Do you have anything enjoyable planned?", frame: "My week has been ___. I managed to ___. This weekend, I plan to ___. What about you?", drill: "Use one connector between ideas, then ask a question that gives the other person a chance to speak.", grammar: "Use have been + adjective for a week continuing until now; use plan to + base verb." },
  { title: "Congratulate someone", goal: "Celebrate another person's success and ask what they will do next.", prompt: "Your friend has passed an important exam. Congratulate them and ask how they prepared.", model: "Congratulations on passing your exam. You worked steadily, and it is great to see your effort pay off. Which part was the most challenging? Do you have another goal you want to work toward now?", frame: "Congratulations on ___. You ___. How did you ___? What will you ___ next?", drill: "Name the achievement, recognise the effort, and finish with a supportive question.", grammar: "Use congratulations on + noun or verb-ing: Congratulations on getting the job." },
  { title: "Talk about your job", goal: "Explain your role, one regular task, and what you enjoy about your work.", prompt: "Describe your job or the kind of work you hope to do.", model: "I work as a customer support assistant. I answer questions, explain services, and help people solve small problems. The most rewarding part is seeing someone feel more confident after I have helped them.", frame: "I work as a ___. My main tasks are ___. I enjoy ___ because ___.", drill: "Use plain words for your responsibilities. Add one example of a task instead of using a long list of job titles.", grammar: "Use work as + role and work in + field. For responsibilities, use the present simple." },
  { title: "Describe your home or village", goal: "Describe a place through its location, features, people, and personal meaning.", prompt: "Describe the home or village where you grew up and say what you remember most.", model: "I grew up in a quiet neighbourhood with a small market nearby. Most people knew one another, and children played outside in the late afternoon. I remember the evening conversations most because they made the area feel welcoming.", frame: "I grew up in ___. It is near ___. The place is ___. I remember ___ because ___.", drill: "Move from the general location to one memorable detail. Use a sensory detail such as a sound, colour, or smell.", grammar: "Use there is/are for features and past simple for memories from childhood." },
  { title: "Give and follow directions", goal: "Give short route instructions in a useful order and check understanding.", prompt: "Explain how to get from a bus stop to a nearby library.", model: "Walk straight until you reach the main road. Turn left at the pharmacy, then cross at the signal. The library is beside the post office. If you reach the bridge, you have gone too far.", frame: "Go straight until ___. Turn ___. Cross ___. The ___ is beside ___.", drill: "Use landmarks and sequence words. Ask the listener to repeat the last step if the route is complicated.", grammar: "Imperatives use the base verb: turn, cross, walk. Add until, then, and beside to show order and place." },
  { title: "Ask for help", goal: "Explain the problem briefly, make a clear request, and thank the person.", prompt: "You cannot find the correct office in a building. Ask someone for help.", model: "Excuse me, I am trying to find the admissions office, but I am not sure which floor it is on. Could you point me in the right direction? Thank you, that is very helpful.", frame: "Excuse me, I'm trying to ___. Could you help me ___? Thank you for ___.", drill: "Start with a polite opener. State what you need in one sentence, then let the other person respond.", grammar: "Use I'm trying to + verb and Could you + base verb for a polite request." },
  { title: "Express happiness and sadness", goal: "Name an emotion and explain the event or reason behind it.", prompt: "Describe a recent moment that made you very happy or a little disappointed.", model: "I felt proud last week because I completed a difficult task without giving up. I was also a little nervous before I shared the result. In the end, my family celebrated with me, which made the moment special.", frame: "I felt ___ when ___. I was ___ because ___. In the end, ___.", drill: "Use one feeling word and explain what happened. You do not need to use dramatic language to sound natural.", grammar: "Use felt + adjective for a past feeling; use because + subject and verb to explain why." },
  { title: "At the pharmacy", goal: "Describe a common health concern and ask a pharmacist a clear question.", prompt: "You have a mild headache and want to ask a pharmacist what information they need before recommending an option.", model: "Hello, I have had a mild headache since this morning. I do not have a fever, but I feel tired. Could you tell me what information you need before suggesting something? I can also speak with a doctor if necessary.", frame: "I have had ___ since ___. I also feel ___. What information do you need?", drill: "Practise describing symptoms and their timing. For real medical decisions, speak with a qualified health professional.", grammar: "Use have had + symptom + since + starting time for a condition continuing now." },
  { title: "Speak with your father", goal: "Share a plan, explain your thinking, and invite advice from a family member.", prompt: "Tell your father about a course or personal goal you want to pursue and ask for his advice.", model: "I am thinking about joining an evening English course. It would give me regular speaking practice, but I need to plan my study time carefully. What do you think would be a realistic schedule for me?", frame: "I'm thinking about ___. It could help me ___. I need to ___. What do you think?", drill: "Explain the goal and one practical concern, then listen to the advice before replying.", grammar: "Use thinking about + verb-ing and could + base verb to talk about a possibility." },
  { title: "Talk with relatives", goal: "Catch up with a relative by sharing news and asking thoughtful questions.", prompt: "You are meeting a cousin you have not seen for a while. Ask about their family and share one update of your own.", model: "It is lovely to see you again. What have you been working on lately? I recently started a new course and have been practising every evening. How is everyone at home?", frame: "It's good to see you. What have you been ___? I recently ___. How is ___?", drill: "Use a greeting, one open question, a short personal update, and one follow-up question.", grammar: "Use have you been + verb-ing to ask about an activity continuing over a recent period." },
  { title: "Discuss money and payments", goal: "Confirm an amount, payment method, and any important timing politely.", prompt: "Ask a service provider to confirm the amount due and whether you can pay by card.", model: "Could you please confirm the total amount I need to pay? Is card payment available, or should I bring cash? If I make the payment today, when will I receive the confirmation?", frame: "Could you confirm ___? Can I pay by ___? When will I receive ___?", drill: "Repeat the amount and date back to check that you understood correctly.", grammar: "Use Could you confirm + noun clause and When will + subject + base verb for clear questions." },
  { title: "Make polite requests", goal: "Request an action with the right level of politeness and give a brief reason.", prompt: "Ask a classmate to share their notes because you missed one part of the lesson.", model: "Would you mind sharing your notes from the last section? I had to step out briefly and missed the explanation. I can send you my notes from the previous class in return.", frame: "Would you mind ___? I missed ___ because ___. I can ___ in return.", drill: "Practise a request to a friend and a request to a manager. Change the wording to fit the relationship.", grammar: "After Would you mind, use verb-ing: Would you mind opening the window?" },
  { title: "Speak with a doctor", goal: "Describe symptoms, duration, and relevant changes in a clear order.", prompt: "Practise explaining a mild symptom to a doctor: when it began, how often it happens, and what makes it better or worse.", model: "I have had a cough for about three days. It is worse at night, but I do not have trouble breathing. I have been drinking water, and I would like to know whether I should book a follow-up visit.", frame: "I've had ___ for ___. It gets worse when ___. I've tried ___. Should I ___?", drill: "Speak in chronological order and answer follow-up questions accurately. Do not guess if you are unsure.", grammar: "Use present perfect for duration and simple present for a pattern: It gets worse at night." },
  { title: "Buy a bus, train, or plane ticket", goal: "Ask about routes, times, seat availability, and ticket conditions.", prompt: "At a ticket counter, ask for a morning ticket to another city and confirm the departure time.", model: "I would like one ticket to Chattogram for tomorrow morning, please. What time does the first bus leave? Is there a seat by the window? Could you also tell me whether the ticket can be changed?", frame: "I'd like one ticket to ___ for ___. What time does ___ leave? Can I ___?", drill: "Confirm the destination, date, and time before finishing the conversation.", grammar: "Use I'd like + noun for a polite order. For schedules, use the present simple: What time does it leave?" },
  { title: "At a hotel", goal: "Check in, confirm a reservation, and ask about useful services.", prompt: "Check in at a hotel and ask when breakfast is served and how to connect to Wi-Fi.", model: "Good evening. I have a reservation under the name Rahman. Could you please confirm the room type? Also, what time is breakfast served, and where can I find the Wi-Fi details?", frame: "I have a reservation under ___. Could you confirm ___? What time is ___?", drill: "Have your name and reservation details ready. Ask one question at a time and repeat key information if needed.", grammar: "Use present passive for service details: Breakfast is served from seven to ten." },
  { title: "English for school life", goal: "Ask a teacher about homework, deadlines, or instructions respectfully.", prompt: "Ask your teacher to explain one part of an assignment you do not understand.", model: "Could you please explain what we need to include in the final paragraph? I understand the first two steps, but I am not sure how to present the conclusion. When is the assignment due?", frame: "Could you explain ___? I understand ___, but I'm not sure about ___. When is ___ due?", drill: "State what you already understand before asking for help with the exact part that is unclear.", grammar: "Use need to + verb for requirements and be due on/by + date for deadlines." },
  { title: "Book an appointment", goal: "Request a suitable time, provide a name, and confirm the appointment details.", prompt: "Call a clinic or office and ask for an appointment on a weekday afternoon.", model: "Hello, I would like to book an appointment for Thursday afternoon if a time is available. My name is Sami Ahmed. Could you tell me the available times and whether I should bring any documents?", frame: "I'd like to book ___. Is ___ available? My name is ___. Should I bring ___?", drill: "Repeat the day, time, and location before ending the call.", grammar: "Use would like to + verb and if + present to ask about availability." },
  { title: "Describe a holiday", goal: "Tell a short holiday story with a place, activity, feeling, and highlight.", prompt: "Describe a holiday you enjoyed or a short trip you would like to take.", model: "Last winter, I visited a quiet riverside town with two friends. We walked through the old market and tried local food. The best part was watching the sunset together because we had not taken a break in months.", frame: "I went to ___ with ___. We ___. My favourite part was ___ because ___.", drill: "Choose three memorable details and put them in the order they happened.", grammar: "Use past simple for finished trip events: visited, walked, tried, watched." },
  { title: "Apologise and repair a mistake", goal: "Apologise clearly, take responsibility, and explain the next step.", prompt: "You are late to a meeting because your bus was delayed. Apologise and explain how you will catch up.", model: "I am sorry I arrived late. The bus was delayed, but I should have sent a message earlier. I will review the notes now and ask if there is one decision I need to follow up on.", frame: "I'm sorry for ___. I should have ___. I will ___ now.", drill: "Avoid long excuses. Say what happened, accept your part, and offer a useful next action.", grammar: "Use sorry for + noun/verb-ing. Use should have + past participle for a past responsibility." },
  { title: "Talk on the phone", goal: "Open a call, identify yourself, explain why you called, and close politely.", prompt: "Call an office to ask whether your application documents have arrived.", model: "Hello, this is Nabila Karim. I am calling to check whether my application documents have arrived. I sent them on Monday by email. Could you please let me know if anything else is needed?", frame: "Hello, this is ___. I'm calling to ___. I sent ___ on ___. Could you let me know ___?", drill: "Speak a little slower on the phone and repeat names, dates, or reference numbers.", grammar: "Use this is + name to identify yourself and I'm calling to + verb to explain the purpose." },
  { title: "Have a conversation with a friend", goal: "Share a story, show interest, and ask a follow-up question.", prompt: "Tell a friend about something you learned recently and ask what they have been learning.", model: "I learned how to make a simple budget last month. It helped me understand where my money goes, and I have started saving a little each week. Have you learned anything useful recently?", frame: "Recently, I learned ___. It helped me ___. Have you learned ___?", drill: "After your friend responds, ask one follow-up question before changing the topic.", grammar: "Use learned + noun or learned how to + verb. Present perfect works for recent experience without a specific date." },
  { title: "Speak at a hospital", goal: "Ask for the right department or service and communicate essential details calmly.", prompt: "At a hospital reception desk, ask where to register for an appointment and what information to provide.", model: "Excuse me, I am here for a scheduled appointment. Could you tell me where I should register? I have my identification and appointment message with me. Please let me know if you need any other information.", frame: "I'm here for ___. Where should I ___? I have ___. Do you need ___?", drill: "Keep the first message short and clear. In an emergency, contact local emergency services rather than relying on language practice.", grammar: "Use should I + base verb for guidance questions and have + noun to list documents." },
  { title: "English for college", goal: "Talk about a class, assignment, or campus activity with a classmate.", prompt: "Tell a classmate which class you enjoy most and ask what they think of the course.", model: "I enjoy the environmental science class because we discuss problems that affect our community. The group project is challenging, but I am learning how to present evidence clearly. Which class do you find most useful?", frame: "I enjoy ___ because ___. The ___ is challenging, but ___. Which class ___?", drill: "Give a reason and one example. Then listen and respond to the other person's view.", grammar: "Use because to join a reason and although/but to show a contrast." },
  { title: "English for university", goal: "Describe a study goal and explain how you are managing academic work.", prompt: "Explain one academic goal for this semester and how you plan to reach it.", model: "This semester, I want to improve my research and presentation skills. I plan to read one article each week, take organised notes, and practise explaining the main idea. I will ask my supervisor for feedback before the final presentation.", frame: "This semester, I want to ___. I plan to ___. I will measure progress by ___.", drill: "Break a large goal into two actions you can repeat each week.", grammar: "Use want to/plan to/will + base verb to describe aims and future steps." },
  { title: "At the bank", goal: "Explain what service you need and ask about identity or account requirements.", prompt: "Ask a bank employee how to update the phone number connected to your account.", model: "Hello, I would like to update the phone number linked to my account. Could you tell me which identification documents I should bring? Will I need to complete a form at the branch?", frame: "I'd like to ___. Which documents should I bring? Will I need to ___?", drill: "Do not say account passwords aloud. Practise asking only about the process and required documents.", grammar: "Use would like to for a service request and should I bring for a polite requirements question." },
  { title: "Make a complaint politely", goal: "Describe a problem, its effect, and the solution you are requesting.", prompt: "A delivery arrived later than the confirmed time. Explain the problem and ask what can be done.", model: "I am calling about a delivery that was expected yesterday but has not arrived. I understand delays can happen, but I need an updated delivery time. Could you check the order and tell me the next step?", frame: "I'm contacting you about ___. It was expected ___. Could you check ___ and tell me ___?", drill: "Keep your voice calm. State the facts, describe the impact briefly, and ask for one reasonable solution.", grammar: "Use was expected to + verb for a plan that did not happen as intended." },
  { title: "Give your opinion", goal: "State a view, support it with a reason, and acknowledge another perspective.", prompt: "Do you think people should study English every day or only before an exam? Explain your view.", model: "I think short daily practice is more useful than studying only before an exam. A little repetition makes speaking feel more familiar. Some people have limited time, so even ten focused minutes can be a realistic start.", frame: "I think ___. My main reason is ___. For example, ___. I understand that ___, but ___.", drill: "Use one clear reason and one example. Mention a different view respectfully before you finish.", grammar: "Use I think + clause, because + reason, and although/however to show contrast." },
  { title: "Express sympathy", goal: "Respond kindly to difficult news without trying to solve everything immediately.", prompt: "A friend tells you they have had a stressful week. Show support and offer a simple form of help.", model: "I am sorry this week has been so difficult for you. It sounds like you have been handling a lot at once. Would it help if I listened, or is there one practical thing I could do for you?", frame: "I'm sorry to hear ___. It sounds like ___. Would it help if ___?", drill: "Speak gently, let the person finish, and avoid comparing their situation with someone else's.", grammar: "Use sorry to hear + clause and Would it help if + past-form question for a gentle offer." },
  { title: "Talk about transport and driving", goal: "Describe a route, commute, or transport preference with reasons.", prompt: "How do you usually travel across your city, and what would make the journey easier?", model: "I usually travel by bus because it is affordable and I can read during the journey. Traffic sometimes makes the trip unpredictable. A more reliable schedule and safer walking paths would make commuting easier for many people.", frame: "I usually travel by ___. It is ___ because ___. The journey would improve if ___.", drill: "Compare two travel options and support your preference with a practical reason.", grammar: "Use travel by + transport, more + adjective for comparisons, and would + verb for a suggestion." },
  { title: "Describe your daily routine", goal: "Describe a routine from morning to evening with clear time markers.", prompt: "Talk for about one minute about a normal weekday and include one habit you want to improve.", model: "I usually wake up around seven and review my plan before breakfast. I work or study through the day, then take a short break in the evening. I want to spend less time on my phone and read for twenty minutes before bed.", frame: "Usually, I ___. After that, I ___. In the evening, I ___. One habit I want to improve is ___.", drill: "Use time phrases to guide the listener. End with a goal and one small action you can repeat.", grammar: "Use usually/often + present simple for routine. Use want to + verb for a personal goal." },
  { title: "Talk about your future plans", goal: "Explain a goal, the reason behind it, and the next practical step.", prompt: "What would you like to achieve during the next year, and what will you do first?", model: "During the next year, I hope to become more confident speaking English. I will practise with short recordings, learn useful phrases for work, and ask a friend to give me feedback once a week. My first step is to make a simple schedule.", frame: "I hope to ___. I chose this goal because ___. First, I will ___. I will track progress by ___.", drill: "Use a realistic next step rather than promising a perfect result. Say when you will begin.", grammar: "Use hope to + verb, will + base verb, and by + time to describe a plan." },
  { title: "Send Eid greetings", goal: "Offer warm holiday wishes and share a brief personal message.", prompt: "Send an Eid greeting to a relative or friend and ask how they are celebrating.", model: "Eid Mubarak to you and your family. I hope the day brings you peace, good health, and time with the people you love. How are you celebrating this year? I hope we can meet soon.", frame: "Eid Mubarak to ___. I hope ___. How are you ___? I hope we can ___.", drill: "Use a warm tone and adapt the message to the person. Add one specific wish or invitation.", grammar: "Use hope + present simple for a wish: I hope you have a peaceful day." },
  { title: "Talk about a favourite movie", goal: "Describe a movie without retelling every scene.", prompt: "Describe a movie you enjoy: its genre, main idea, what you liked, and who might enjoy it.", model: "One film I enjoyed is a family drama about two siblings who start a small business. I liked the realistic dialogue and the way their relationship changed. I would recommend it to people who enjoy stories about resilience.", frame: "A movie I like is ___. It is about ___. I enjoyed ___ because ___. I would recommend it to ___.", drill: "Summarise the plot in one sentence, then spend more time explaining your reaction.", grammar: "Use is about + noun/verb-ing and would recommend it to + audience." },
  { title: "Talk about a sport you enjoy", goal: "Explain how a sport works for you and why you enjoy it.", prompt: "Describe a sport you play or watch and say what you find interesting about it.", model: "I enjoy watching cricket with my cousins because it gives us a reason to spend time together. I like the strategy as much as the competition. I do not play often, but I sometimes join a casual game on weekends.", frame: "I enjoy ___ because ___. What interests me most is ___. I usually ___.", drill: "You do not need technical vocabulary. Explain the feeling, people, or routine connected with the sport.", grammar: "Use enjoy + noun/verb-ing, and use sometimes/often to describe frequency." },
  { title: "At a restaurant", goal: "Order a meal, ask about ingredients, and request the bill courteously.", prompt: "At a restaurant, ask what a dish contains, order a meal, and request the bill later.", model: "Could you tell me what comes with the vegetable curry? I would like that with rice, please. Could I also have a glass of water? Everything was very good; may I have the bill when you are ready?", frame: "Could you tell me what is in ___? I'd like ___, please. May I have ___?", drill: "Practise the order first, then a polite question about ingredients and a simple closing request.", grammar: "Use Could I have/May I have for polite requests and what comes with to ask about a meal." },
  { title: "At the airport", goal: "Ask about check-in, gates, and boarding while confirming key details.", prompt: "At an airport information desk, ask where to check in for a domestic flight and when boarding begins.", model: "Excuse me, could you tell me where the check-in desk is for flight BG 214? I have my ticket and identification ready. Which gate should I go to, and when does boarding begin?", frame: "Where is the check-in desk for ___? Which gate should I use? When does boarding begin?", drill: "Say the flight number clearly. Repeat the gate and boarding time to confirm you heard correctly.", grammar: "Use could you tell me where + statement word order: where the desk is." },
  { title: "Welcome a visitor to Bangladesh", goal: "Introduce a visitor to local food, places, and everyday customs with care.", prompt: "A visitor has arrived in Bangladesh. Welcome them and suggest one local experience.", model: "Welcome to Bangladesh. I hope you have a comfortable stay. If you have time, you could visit the old part of Dhaka and try a local breakfast. Please tell me if you need help finding your way around.", frame: "Welcome to ___. You could visit ___. I recommend trying ___. Let me know if ___.", drill: "Offer suggestions without assuming what the visitor likes. Explain why you recommend one place or activity.", grammar: "Use could + base verb for a suggestion and let me know if for an offer of help." },
  { title: "Make a new friend", goal: "Find a shared interest and turn a first conversation into a friendly connection.", prompt: "You meet someone at a community event. Find a shared interest and suggest a simple way to keep in touch.", model: "I enjoyed talking with you about photography. I have been trying to take better pictures around the city. Would you like to visit the weekend photo exhibition together? I can send you the details if you are interested.", frame: "I enjoyed talking about ___. I also ___. Would you like to ___? I can ___.", drill: "Look for a genuine shared interest, make a low-pressure invitation, and give the other person an easy way to decline.", grammar: "Use enjoy + verb-ing and Would you like to + verb for an invitation." },
  { title: "Discuss an author, athlete, or actor", goal: "Describe a public figure through their work and why it matters to you.", prompt: "Talk about an author, athlete, actor, or other public figure whose work you respect.", model: "I admire a local author who writes stories about ordinary families. Her characters feel believable, and the settings remind me of places I know. I respect the care she takes with language, and her books have encouraged me to read more.", frame: "I admire ___. They are known for ___. I respect ___ because ___. Their work has encouraged me to ___.", drill: "Focus on the person's work and your own reaction. Use one example instead of listing achievements.", grammar: "Use who/that clauses to add detail: an author who writes about family life." },
  { title: "Speak with a teacher", goal: "Ask for feedback or clarification and explain what you have already tried.", prompt: "Ask a teacher how you can improve one part of an assignment or speaking skill.", model: "I have practised the presentation twice, but I still speak too quickly in the middle. Could you suggest one way to slow down and make the main points clearer? I can practise the revised version before next week.", frame: "I have tried ___. I still find ___ difficult. Could you suggest ___? I will practise ___.", drill: "Describe your effort before asking for advice. Ask for one specific suggestion you can apply.", grammar: "Use have tried + noun/verb-ing for effort up to now and could suggest for a polite request." },
  { title: "Make a plan together", goal: "Suggest options, compare practical details, and agree on the next step.", prompt: "Plan a low-cost day out with a friend. Suggest two options and agree on when to meet.", model: "We could visit the public museum or walk beside the river. The museum is cooler if it rains, while the riverside walk costs nothing. Shall we check the forecast tonight and decide where to meet at ten?", frame: "We could ___ or ___. ___ is better if ___. Shall we ___ and then ___?", drill: "Offer two options, compare one practical factor, and finish by confirming who will do what.", grammar: "Use could for options, while for contrast, and Shall we + verb to make a shared plan." },
  { title: "Job interview conversation", goal: "Answer a job question with a relevant example and a clear result.", prompt: "Tell an interviewer about a time you handled a difficult task with other people.", model: "In my last project, our team had to prepare a report within a short deadline. I organised the research tasks and checked that everyone had the latest information. We submitted the report on time, and I learned to raise risks early.", frame: "The situation was ___. My task was ___. I ___. The result was ___. I learned ___.", drill: "Use a short Situation, Task, Action, Result structure. Spend the most time on what you personally did.", grammar: "Use past simple for actions and past continuous only for background activity." },
  { title: "Visa interview practice", goal: "Answer study or travel questions directly and support the answer with accurate facts.", prompt: "Practise explaining your main reason for travelling and what you plan to do afterward.", model: "I plan to study information systems because the course includes practical project work that matches my goals. I have reviewed the program requirements and prepared the supporting documents. After completing the course, I intend to follow the plan stated in my application.", frame: "I plan to travel for ___. I chose ___ because ___. I have prepared ___. Afterward, I plan to ___.", drill: "Answer truthfully and consistently with your documents. Keep the response direct and do not invent details.", grammar: "Use plan to + verb and have prepared + noun for completed preparation." },
  { title: "Speak in the office", goal: "Give a concise work update with status, obstacle, and next action.", prompt: "Update a manager on a task that is mostly complete but waiting for one person's review.", model: "The draft report is complete, and I have checked the figures. I am waiting for one review before I send the final version. I expect to finish tomorrow morning, and I will flag any change to the deadline today.", frame: "The task is ___. I have ___. I'm waiting for ___. I expect to ___.", drill: "Lead with the status, then name the blocker and the next time you will update the person.", grammar: "Use present perfect for work completed with a current result and expect to + verb for a forecast." },
  { title: "Introduce yourself formally", goal: "Give a professional introduction suited to a meeting, panel, or official event.", prompt: "Introduce yourself to a formal audience in about thirty seconds.", model: "Good morning. My name is Farhan Ahmed, and I work in community health education. My experience includes coordinating workshops and creating clear learning materials. I am pleased to join you today and look forward to hearing your ideas.", frame: "Good ___. My name is ___. I work in ___. My experience includes ___. I look forward to ___.", drill: "Keep your introduction relevant to the audience. Use a steady pace and stop after the essential details.", grammar: "Use includes + noun/verb-ing to summarise experience: My work includes training volunteers." },
  { title: "Tell a story", goal: "Tell a short story with a setting, a challenge, a turning point, and a result.", prompt: "Tell a story about a time a small mistake taught you something useful.", model: "One morning, I left home without checking the meeting time. When I arrived, the session had already started. I apologised, listened carefully, and made a reminder for next time. Since then, I check my calendar before leaving.", frame: "One day, ___. The problem was ___. Then I ___. In the end, ___. Since then, ___.", drill: "Use first, then, and in the end. Keep the story focused on one event and one lesson.", grammar: "Use past simple for the event and since then + present perfect for a lesson continuing to now." },
  { title: "Take part in a discussion", goal: "Build on an idea, disagree respectfully, and invite another viewpoint.", prompt: "Discuss whether schools should give students more group projects. Give a view and respond to another perspective.", model: "Group projects can help students practise communication and share responsibility. I agree that they take extra planning, but clear roles can make the work fairer. I would also like to hear how other students feel about assessment.", frame: "I see your point about ___. I would add ___. One concern is ___. What do you think about ___?", drill: "Refer to the other person's idea before adding yours. Disagree with the point, not the person.", grammar: "Use I see your point, however/but + clause, and What do you think about + noun/verb-ing?" },
  { title: "Host an event", goal: "Welcome an audience, introduce the program, and move smoothly between speakers.", prompt: "Open a small community event and introduce the first speaker.", model: "Good afternoon, everyone, and welcome to our community learning day. Thank you for being here. We will begin with a short talk on practical study habits, followed by a question session. Please join me in welcoming our first speaker, Ms. Karim.", frame: "Good ___. Welcome to ___. Today we will ___. Please join me in welcoming ___.", drill: "Speak clearly, pause after the welcome, and pronounce each speaker's name before the event.", grammar: "Use will + base verb to outline a program and please join me in + verb-ing for an introduction." },
  { title: "Give a presentation", goal: "Present a main message with a signposted structure and a concise closing.", prompt: "Give a one-minute presentation on one habit that helps people learn a language.", model: "Today I will share one habit that helps me learn English: practising aloud for a few minutes each day. First, I choose a short topic. Next, I speak without stopping to correct every mistake. Finally, I listen again and choose one thing to improve. Small, regular practice makes progress easier to notice.", frame: "Today I will discuss ___. First, ___. Next, ___. Finally, ___. To conclude, ___.", drill: "Prepare five keywords, not a full script. Look up between points, use signposts, and finish by repeating the main message.", grammar: "Use first/next/finally to signal order and to conclude + noun/verb-ing for a summary." },
];

export const SPOKEN_ENGLISH_BOOK_LESSONS: SpeakingCourseLesson[] = SPOKEN_BOOK_CONTENT.map((lesson, index) => ({
  ...lesson,
  id: `spoken-book-class-${String(index + 1).padStart(2, "0")}`,
  stage: index < 20 ? "SPOKEN ENGLISH BOOK · EASY" : index < 40 ? "SPOKEN ENGLISH BOOK · MEDIUM" : "SPOKEN ENGLISH BOOK · HARD",
  minutes: index < 20 ? 8 : index < 40 ? 10 : 12,
}));

export const ALL_SPEAKING_LESSONS: SpeakingCourseLesson[] = [...SPEAKING_LESSONS, ...SPOKEN_ENGLISH_BOOK_LESSONS];

